plist.dict:
method
{{ cookiecutter.ios_export_method | e }}
provisioningProfiles

    {{ cookiecutter.bundle_id | e }}
    {{ cookiecutter.ios_provisioning_profile | e }}


{% if cookiecutter.ios_team_id %}
teamID
{{ cookiecutter.ios_team_id | e }}
{% endif %}

{% if cookiecutter.ios_signing_certificate %}
signingCertificate
{{ cookiecutter.ios_signing_certificate | e }}
{% endif %}

{% macro render_value(value) -%}
{% if value is string -%}
{{ value | e }}
{% elif value is boolean -%}
<{{ "true" if value else "false" }}/>
{% elif value is integer -%}
{{ value }}
{% elif value is float -%}
{{ value }}
{% elif value is mapping -%}

    {{ render_dict(value) }}

{% elif value is sequence -%}  {# Support for lists/arrays #}

    {% for item in value -%}
        {{ render_value(item) }}
    {% endfor -%}

{% endif -%}
{% endmacro -%}
{% macro render_dict(d) -%}
{% for key, value in d.items() -%}
{{ key | e }}
{{ render_value(value) }}
{% endfor -%}
{% endmacro -%}
{{ render_dict(cookiecutter._options.ios_export_options) }}
